<?php
// Startup/customer receipts without a posted original order. No schema changes.
function unlinked_return_batch($b){$rows=json_decode($b['rows_json']??'[]',true)?:[];return !empty($rows[0]['unlinked_receipt']);}
function unlinked_return_reference($value){$s=mb_strtoupper(preg_replace('/\s+/u','',trim((string)$value)));if($s===''||mb_strlen($s)>100)throw new Exception('Tracking / receipt reference is required, up to 100 characters.');return $s;}
function unlinked_return_rows_check($b,$rows){
 $first=$rows[0]??[];$ref=unlinked_return_reference($first['receipt_reference']??'');$platform=stock_platform($first['platform']??'');$hash=hash('sha256','unlinked-receipt|'.$platform.'|'.$ref);
 if(($b['file_hash']??$hash)!==$hash)throw new Exception('Receipt identity changed. Cancel this draft and prepare a new receipt.');
 $q=db()->prepare("SELECT batch_ref FROM return_batches WHERE file_hash=? AND id<>? AND status IN ('Review','Posted') LIMIT 1");$q->execute([$hash,(int)($b['id']??0)]);if($old=$q->fetchColumn())throw new Exception('This receipt was already entered: '.$old.'. Open the existing batch.');
 $seen=[];foreach($rows as $r){if(empty($r['unlinked_receipt'])||($r['platform']??'')!==$platform||unlinked_return_reference($r['receipt_reference']??'')!==$ref)throw new Exception('Do not mix receipt references or normal order returns in this batch.');if(empty($r['not_counted_ack']))throw new Exception('Confirm these units were not already included in beginning balance or another receipt.');$pid=(int)$r['product_id'];if(isset($seen[$pid]))throw new Exception('Use one line per product; consolidate its quantity.');$seen[$pid]=true;$order=trim($r['external_order']??'');$expected=$order!==''?$order:'UNLINKED-'.substr($hash,0,48);if(($r['order']??'')!==$expected)throw new Exception('Original order reference changed. Prepare the receipt again.');if($order!==''){$q=db()->prepare("SELECT id FROM outflows WHERE platform=? AND order_id=? AND type='Order' AND reversed_by_request IS NULL LIMIT 1");$q->execute([$platform,$order]);if($q->fetchColumn())throw new Exception('The original order is now available. Use Find Order Items in normal Return Orders.');if(om_ready()){$q=db()->prepare('SELECT id FROM om_orders WHERE platform=? AND order_no=? LIMIT 1');$q->execute([$platform,$order]);if($q->fetchColumn())throw new Exception('This order is already registered. Check its dispatch status and use normal Return Orders.');}}}
}
function unlinked_return_stage($input,$file=null){
 if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');if(empty($input['physical_ack'])||empty($input['not_counted_ack']))throw new Exception('Confirm physical receipt and that these units were not already counted.');
 $date=process_date($input['txn_date']??'');require_open_inventory_date($date);$platform=stock_platform($input['platform']??'');$ref=unlinked_return_reference($input['receipt_reference']??'');$order=trim((string)($input['order_id']??''));if(strlen($order)>100)throw new Exception('Original Order ID must be at most 100 characters.');$hash=hash('sha256','unlinked-receipt|'.$platform.'|'.$ref);$rows=[];
 foreach($input['items']??[] as $item){if(empty($item['product_id'])&&trim((string)($item['qty']??''))==='')continue;$p=active_product((int)($item['product_id']??0));$rows[]=['row'=>count($rows)+1,'date'=>$date,'platform'=>$platform,'order'=>$order!==''?$order:'UNLINKED-'.substr($hash,0,48),'external_order'=>$order,'product_id'=>(int)$p['id'],'item'=>$p['name'],'qty'=>whole_number($item['qty']??'','Received quantity',1),'condition'=>$item['condition']??'','remarks'=>'Actual customer return; original order not recorded. Receipt: '.$ref,'transaction_kind'=>'Return Order','unlinked_receipt'=>true,'receipt_reference'=>$ref,'not_counted_ack'=>true];}
 if(!$rows||count($rows)>200)throw new Exception('Enter 1 to 200 received product lines.');$probe=['revision'=>1,'status'=>'Review','file_hash'=>$hash,'rows_json'=>json_encode($rows)];$a=return_analysis($probe);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));$stored=!empty($file['tmp_name'])?store_upload($file,'return_attachments','RETURN'):null;
 return return_stage($rows,'Customer Return · '.$ref,$stored,$hash);
}
function unlinked_return_link($id,$input){
 if(!can_action('return_confirm'))throw new Exception('Return receiving access required.');return process_transaction(function()use($id,$input){$b=return_batch($id,true);if($b['status']!=='Posted'||!unlinked_return_batch($b))throw new Exception('Only a posted unlinked receipt can be linked.');$rows=json_decode($b['rows_json'],true);if(!empty($rows[0]['linked_order']))throw new Exception('This receipt is already linked.');$order=trim((string)($input['order_id']??''));if($order===''||strlen($order)>100)throw new Exception('Enter the original Order ID.');$ids=array_unique(array_column($rows,'product_id'));sort($ids,SORT_NUMERIC);foreach($ids as $pid)db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);
 foreach($rows as &$r){if(!empty($r['external_order'])&&$r['external_order']!==$order)throw new Exception('Original Order ID differs from the ID recorded on this receipt. Ask Admin to review the source documents.');$balance=order_return_balance($r['platform'],$order,$r['product_id']);$own=$r['order']===$order?(int)$r['qty']:0;if($balance['original']<=0||$balance['returned']-$own+(int)$r['qty']>$balance['original'])throw new Exception('Original posted order/product is missing or has insufficient remaining return quantity.');$q=db()->prepare('SELECT MIN(txn_date) FROM outflows WHERE platform=? AND order_id=? AND product_id=? AND type=\'Order\' AND reversed_by_request IS NULL');$q->execute([$r['platform'],$order,$r['product_id']]);if($q->fetchColumn()>$r['date'])throw new Exception('Original dispatch is dated after this receipt. Check the original order.');$q=db()->prepare('UPDATE posted_returns SET original_ref=? WHERE batch_id=? AND product_id=? AND reversed=0');$q->execute([$order,$id,$r['product_id']]);if($q->rowCount()===0){$q=db()->prepare('SELECT id FROM posted_returns WHERE batch_id=? AND product_id=? AND reversed=0');$q->execute([$id,$r['product_id']]);if(!$q->fetchColumn())throw new Exception('This receipt has been reversed.');}$r['linked_order']=$order;$r['linked_by']=current_user()['id'];$r['linked_at']=date(DATE_ATOM);}unset($r);
 db()->prepare('UPDATE return_batches SET rows_json=?,revision=revision+1 WHERE id=?')->execute([json_encode($rows),$id]);inflow_sync_return_history($id);om_return_sync($rows[0]['platform'],$order,$id);audit('Link original order to received return','Return',$b['batch_ref'],'Original order '.$order.'; receipt '.$rows[0]['receipt_reference'].'; no quantity or stock movement.');
 });
}
function unlinked_return_form(){
 if(!can_action('return_confirm'))return;$draft=$_SESSION['unlinked_return_draft']??[];
 echo '<div class="card"><h3>Return — Original Order Not in System</h3><p>Receive actual customer returns from older orders. Quantities increase Sellable or Non-Sellable and Total Physical once. For recorded orders, use <a href="?page=inflow&amp;entry=manual">Find Order Items</a>.</p><form method="post" enctype="multipart/form-data" action="actions.php">';workflow_hidden('receiving_unlinked_stage',['return'=>'inflow&entry=manual&unlinked=1']);echo '<div class="batch-fields"><label>Received Date<input type="date" name="txn_date" value="'.e($draft['txn_date']??date('Y-m-d')).'" max="'.date('Y-m-d').'" required></label><label>Platform<select name="platform">';foreach(['Shopee','Lazada','TikTok'] as $platform)echo '<option '.(($draft['platform']??'Shopee')===$platform?'selected':'').'>'.$platform.'</option>';echo '</select></label><label>Tracking / Receipt Reference<input name="receipt_reference" value="'.e($draft['receipt_reference']??'').'" maxlength="100" required></label><label>Original Order ID · Optional<input name="order_id" value="'.e($draft['order_id']??'').'" maxlength="100"></label><label>One Batch Attachment · Optional<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg"></label></div><div class="table-wrap"><table class="table"><thead><tr><th>Products / SKU</th><th>Received Qty</th><th>Condition</th><th></th></tr></thead><tbody data-unlinked-lines>';
 $items=array_slice(array_values($draft['items']??[['product_id'=>'','qty'=>'','condition'=>'Good Item']]),0,200);foreach($items as $i=>$item){echo '<tr><td>'.picker('items['.$i.'][product_id]','Select received product...',false,$item['product_id']??'',false).'</td><td><input type="number" name="items['.$i.'][qty]" value="'.e($item['qty']??'').'" min="1" max="100000000" step="1"></td><td><select name="items['.$i.'][condition]">';foreach(['Good Item'=>'Sellable','Damaged / Leak'=>'Damaged / Leak','For Repackaging'=>'For Repackaging'] as $v=>$label)echo '<option value="'.e($v).'" '.(($item['condition']??'')===$v?'selected':'').'>'.$label.'</option>';echo '</select></td><td><button type="button" class="btn ghost" data-unlinked-remove>Remove</button></td></tr>';}
 echo '</tbody></table></div><button type="button" class="btn secondary" data-unlinked-add>+ Add Item Line</button><p class="muted small">Use one line per product. A receipt reference identifies one physical receipt; use its original tracking / receipt number.</p><label class="ack"><input type="checkbox" name="physical_ack" value="1" required> These quantities were physically received.</label><label class="ack"><input type="checkbox" name="not_counted_ack" value="1" required> These units were not already included in Beginning Balance or another inflow. Receiving them adds to Total Physical.</label><div class="modal-actions"><a class="btn ghost" href="?page=inflow&amp;entry=manual">Back to Order Lookup</a><button class="btn primary">Validate &amp; Review</button></div></form></div><script src="assets/unlinked_returns.js" defer></script>';
}
function unlinked_return_history($b){
 if(!unlinked_return_batch($b))return;$rows=json_decode($b['rows_json'],true);$r=$rows[0];echo '<div class="alert info"><strong>Customer Return · Original Order Not in System</strong><br>Receipt: '.e($r['receipt_reference']).'<br>'.(!empty($r['linked_order'])?'Linked original order: '.e($r['linked_order']).' · '.e($r['linked_at']):'Original order: '.e($r['external_order']?:'Not provided').' · Awaiting original-order link').'<br>Linking does not add stock again.</div>';
 if($b['status']==='Posted'&&empty($r['linked_order'])&&can_action('return_confirm')){echo '<form method="post" action="actions.php">';workflow_hidden('receiving_unlinked_link',['batch_id'=>$b['id'],'return'=>'manual_receiving&id='.$b['id']]);echo '<label>Original Order ID<input name="order_id" maxlength="100" value="'.e($r['external_order']).'" required></label><button class="btn secondary">Link Original Order · No Stock Change</button></form>';}
 if($b['status']==='Review')echo '<p>To correct this receipt, cancel this unposted batch and enter it again. No quantity has been added yet.</p>';
}
